// W2 Looms · app/guide.js — The Guide panel: what every tab shows, how its figures are worked out, and what to do with them.
// One of the classic scripts index.html loads in order; they share one scope (no modules, no build step).
// The guide opens on the section for the tab you are on, has its own contents and search, and shows the app's real marks
// (arrows, bm / best, pills) and two small example charts drawn with the app's own chart code. A Plant view user sees every
// section except Data health and Access, with Costing in the plant's own figures.
'use strict';
const GUIDE_TABS = {actions: 'g-actions', quality: 'g-quality', benchmarks: 'g-benchmarks', cfm: 'g-cfm', erpm: 'g-erpm', pressure: 'g-pressure',
  utilisation: 'g-utilisation', warp: 'g-warp', costing: 'g-costing', targets: 'g-targets', data: 'g-data', access: 'g-access', fabric: 'g-fabric'};
let GUIDE_Q = '';

function guideSections() {
  const tolR = S().tol_rpm_pct, tolA = S().tol_air_pct, eff = f0(EFF_BAD()), etg = f0(ERPM_TGT * 100);
  const P = (t) => el('p', {text: t});
  const B = (...xs) => el('ul', {class: 'gl'}, xs.filter(Boolean).map((x) => el('li', {}, x)));
  const K = (k, ...rest) => el('span', {}, el('b', {text: k + ' '}), ...rest);
  const bm = (t, cls) => el('button', {type: 'button', class: 'bmb' + (cls ? ' ' + cls : ''), tabindex: -1, text: t});
  const up = (t) => el('span', {class: 'delta up-bad', text: t}), dn = (t) => el('span', {class: 'delta up-good', text: t});
  // a small example trend: a loom's air per 1,000 picks against its benchmark and best, with a beam change marked
  const exTrend = () => lineChart({plain: true, noOpen: true, aria: 'Example trend', dates: ['2026-11-01', '2026-11-02', '2026-11-03', '2026-11-04', '2026-11-05', '2026-11-06', '2026-11-07'],
    series: [{name: 'Air per 1,000 picks', vals: [37.6, 36.4, 38.1, 36.9, 35.8, 35.2, 34.6], color: CC[0]}], refs: [{v: 33.4, label: 'Bm 33.4'}, {v: 32.2, label: 'Best 32.2'}], fmt: (v) => pn(v, 1)});
  const exFall = () => waterfall([{label: 'Yesterday', v: 24.4, total: true}, {label: 'Volume', v: 0.49}, {label: 'POWER', v: 0.37}, {label: 'OPERATOR', v: -0.02}, {label: 'All other', v: 0.04}, {label: 'Today', v: 25.28, total: true}], 'Example: why cost per pick moved');
  const plant = isPlant();
  const ed = typeof canEdit === 'function' && canEdit();   // Reload data and Save all: the edit targets and admin roles only
  const own = typeof fxOn === 'function' && fxOn();   // Round E: fabrics in the search (owner, analysis on)

  const all = [
    {id: 'g-start', grp: 'Start here', title: 'How to read this app', body: [
      P('Each tab answers one question about the floor. The loom tabs (Actions to Warp breaks) are built from the Toyota shift reports, one point per complete day (both shifts in). Costing is built from the plant\'s own costing file. Targets and the switches are yours to set.'),
      B(K('The date chip at the top of the page', 'shows the app as it stood on an earlier day: pick a date from it. The Costing tab has its own day list at its top, labelled Day. Benchmarks, best and targets stay today\'s.'),
        K('190 cm / 280 cm / Both widths', 'filters the loom tabs by loom width. Since 24 Nov it is its own row that stays at the top of the screen while you scroll, above the section bar, on laptop and phone. It is not shown on Pressure, which always covers both widths because one compressor serves the whole floor, nor on Costing or the admin tabs, which do not follow the width.'),
        K('Refresh', '(the round-arrow icon: at the foot of the side menu on a laptop, in the top bar on a phone; on a laptop, point at it to see its name) fetches the latest figures from the database.' + (ed ? ' It does not start the daily run: Reload data (on Data health and the Needs a head group card) does that.' : '')),
        K('Search', 'finds a tab, a card, a loom, a head group or a Guide heading and takes you there (see "Search, Favourites and shortcuts" below).'),
        K('Filter tables on this page', '(the box above the tables) keeps only the table rows that match: a loom number, a head group or any text.'),
        K('The section bar', 'under the title jumps between the sections of a long tab; "All sections" lists them.'),
        K('Sorting basis', `above every table of 3 or more rows and every ranked bar chart: pick the column (or figure) to sort on, then ↑ Ascending or ↓ Descending. Most open worst first on their own main figure (dates newest first); the rest open on "As shown", the order the card was built in, which you can also pick. Gaps ("—", "not priced") and worded cells always sort last, a Total row stays last, and a cell sorts on its main figure, not the small print under it. A chart that draws only its first 8, 15 or 25 bars ranks every row on the basis first, then draws the first ones (its Show all button, where it has one, draws them all; the card says when the chart shows fewer than its table).${own ? ' On Quality, Current vs reference opens on Profit, lowest first (the old By picks / By profit switch is now this picker); on Realisation, By loom opens on Profit (loom cost) per loom per day, lowest first.' : ''} Where less is worse (effective RPM${own ? ', realisation' : ''}) the gap is "Shortfall" (how far below the reference), largest first; elsewhere it is "Excess" (how far over it). Your choice follows your sign-in email.`),
        K('The = mark (Working)', 'after a tile\'s name or a card\'s title opens the Working for that figure: the formula in words, the same line with the day\'s own figures, ending on the result with its unit (the figure on the screen), what makes it show "—" and what to do next, and a folded example with made-up figures. The sheet has up to five headings, in this order (a few entries that only explain have In words alone): In words, With this day\'s figures, Result, When it shows "—", and Example with made-up figures (folded: tap it to open it). The × at its top right, named "Close the Working", closes it; "More in the Guide ›" at its foot closes it and opens this Guide where that figure is explained. On a laptop it sits at the top right of a tile and just after a card\'s title; on a phone the same, and the Working fills the screen. Every "this week vs last week" line that compares two weeks ends with one too. On a phone the mark has no name beside it: it is the small = square at the top right of a tile or next to a card\'s title. The search finds each one as "Working: " and the name of its tile or card as the screen shows it; a card\'s count after its "·" is left off, as for cards in the search. A name met in more than one place adds what it is and where: "tile on" or "card on" and its tab, or "tile in" and the card it sits in (for example "Working: Picks, tile on Costing", or "Working: Cost per pick saved, tile in If every loom ran at its reference CFM"). Each tab\'s section of this Guide ends with links to the Working of the marks on that tab, under the same names; a link closes the Guide and opens the Working on its tab. A tile or card the day shown does not draw is not listed, and a mark inside a loom\'s or head group\'s panel opens from that panel only.'),
        K('Click almost anything:', 'a loom number opens that loom, a head group opens its looms and benchmark, a bm or best figure shows the loom-days behind it, a chart point opens that day.')),
      el('p', {class: 'note', text: 'A red line under the title means the latest data is old: the plant\'s files may be missing or the daily run may have stopped.'})]},
    {id: 'g-marks', grp: 'Start here', title: 'Colours, arrows and marks', body: [
      el('div', {class: 'gmarks'},
        el('div', {}, el('span', {class: 'pill good', text: 'complete'}), ' ', el('span', {class: 'pill bad', text: 'missing'}), ' ', el('span', {class: 'pill warn', text: 'provisional'}), ' ', el('span', {class: 'pill info', text: 'likely beam'})),
        el('div', {}, dn('▼ −0.4 vs prior-days avg'), el('span', {class: 'note', text: '  green: moved the good way'})),
        el('div', {}, up('▲ +0.9 vs previous day'), el('span', {class: 'note', text: '  red: moved the bad way'})),
        el('div', {}, el('b', {text: '35.1 '}), el('span', {style: 'color:var(--bad)', text: '▲ '}), bm('bm 29.6', 'miss'), ' · ', bm('best 26.7', 'best'), el('span', {class: 'note', text: '  the missed reference is underlined in red'}))),
      B(K('bm', '= benchmark: what this head group normally achieves on this width (see Benchmark and best).'),
        K('best', '= the single best loom-day on record for it.'),
        K('tgt', '= your target from the Targets tab.'),
        K('line', `= the efficiency line: below ${eff}% is bad on any quality.`),
        K('▼ ▲ on a figure', 'means it is worse than a reference by more than its tolerance. Green or red on a change says whether it moved the good or bad way, not up or down.'),
        K('Toggle boxes', 'above a chart switch its lines on and off; your choice is kept on this device.'))]},
    {id: 'g-search', grp: 'Start here', title: 'Search, Favourites and shortcuts', body: [
      P('One search finds every tab and card you can see, plus looms, head groups and the headings of this Guide' + (own ? ', and fabrics' : '') + '. Pick a result to go there: a card is scrolled to and opened if it was folded; a loom or head group opens its panel. It only finds what your own screens show' + (plant ? ', so no money sections.' : '.')),
      B(K('On a laptop:', 'the search box sits right under the logo at the top of the side menu. Press / or Ctrl K (⌘ K on a Mac) to jump to it from anywhere. With the box empty it lists Recent; the keys are listed under the results.'),
        K('On a phone:', 'tap the search icon (the magnifier) in the top bar, next to Refresh (the round-arrow icon). A full-screen sheet opens with the search box, Favourites (folded) and Recent; Close shuts it.'),
        K('Favourites:', 'the 5 tabs and cards you open most, counted over the last 30 days (opening a tab, or a card from the search). The list starts folded: tap Favourites to open it. On a laptop it is under the search box; on a phone it is in the search sheet and at the top of More.'),
        K('Recent:', 'the last 10 places you opened (tabs, cards, looms, head groups, Guide headings) and searches you picked, newest first. Clear empties it.'),
        K('Same on every device you sign in on:', 'Favourites and Recent are kept against your sign-in email, so the laptop and the phone show the same lists.'),
        K('Shortcuts (laptop keyboard):', '1 to 9 open the first nine tabs in the side menu (1 Actions, 2 Quality, 3 Benchmarks, 4 CFM, 5 Effective RPM, 6 Pressure, 7 Utilisation, 8 Warp breaks, 9 Costing); / or Ctrl K opens the search; g then l opens it ready for a loom number (type it, then Enter); Esc closes it. They do nothing while you type in a box or while a panel is open.')),
      el('p', {class: 'note', text: 'The search and the shortcuts only go places and open looms: they never change loom, costing, target or fabric data. All they keep is your own Favourites and Recent.'})]},
    {id: 'g-bench', grp: 'Ideas used everywhere', title: 'Benchmark, best and target', body: [
      P('Every head group gets a benchmark per loom width from all of its history. For RPM and effective RPM it is the 90th percentile of its loom-days (beaten by only 1 day in 10). For air per 1,000 picks and main pressure it is the 10th percentile (lower is better). Nothing is filtered out as an outlier.'),
      P('Best is the single best loom-day behind it: fastest RPM, lowest air, lowest pressure. Target is what you set on the Targets tab; the effective RPM target is ' + etg + '% of your target RPM.'),
      P('A benchmark is provisional (yellow) until it rests on 15 loom-days on 5 dates from 2 looms; read its gaps as indicative until then. Click any bm or best figure to see the exact loom-days and the arithmetic.')]},
    {id: 'g-panna', grp: 'Ideas used everywhere', title: 'Double panna (280 cm)', body: [
      P('A 280 cm loom weaves two panels, so each machine pick makes two fabric picks. Picks and air per 1,000 picks count both panels; RPM, CFM, pressure and the warp-break rate stay as the loom reads them. A head group that runs single panna on 280 cm can be switched on the Targets tab, and that applies at once.')]},
    {id: 'g-trends', grp: 'Ideas used everywhere', title: 'Trends and periods', body: [
      P('Actions and the CFM, Effective RPM, Pressure, Utilisation and Warp breaks tabs each have a Trend card for one head group or one loom (Actions\' card has every loom metric in its Metric list; it was on Quality before 24 Nov). The dashed lines are today\'s benchmark (Bm) and best, even when you look at an earlier day, and they stay flat: they belong to the quality the loom or head group is on at the end of the period (CFM worked at its latest RPM). A B on the date axis marks a beam change; an arrow at the top marks the day a loom changed head group, and the days before it are drawn but not judged, because the lines are another quality\'s. Click a point for that day, the ↗ next to a loom or head group in any table to load it into the card, and "View all trends" for every metric at once.'),
      el('div', {class: 'gex'}, el('div', {class: 'note', text: 'Example: a loom coming down towards its benchmark (made-up figures)'}), exTrend()),
      P('Period switches (7, 14, 30 days, month to date, Dates) pick the days a chart covers; your choice is kept on this device. On Costing, a period longer than 12 days also offers Weekly (one point per Monday–Sunday week), and a daily chart over 14 days shows 14 days at a time: swipe, drag, or use Earlier / Later. The "7-day average" box adds a smoothed line and fades the daily one.'),
      P('This week vs last week: under the period buttons, each period bar also compares its card\'s main figure for this week against last week, whatever period is picked. This week is the 7 days up to the day shown (on Costing, the day picked there; elsewhere, the day at the top of the app); last week is the 7 days before. They are rolling, not Monday to Sunday. Per-pick figures are weighted by picks (the week\'s rupees ÷ its picks), rates are worked from the week\'s totals, and picks, metres and stock are an average a day. A week with days missing (no file came, or a day left out of costing) says how many it has, for example "5 of 7 days", and compares the average of those days. A week with no day at all shows "—", never 0: the comparison appears once both weeks have a day, so pick a later day with the date chip at the top of the page (on Costing, the list labelled Day) or check again after the daily run; if a week stays empty, ' + (!plant && typeof fxIsOwner === 'function' && fxIsOwner() ? 'see Files per day on Data health for the missing days.' : 'tell the owner.') + ' Green means better, red worse, grey neither (closing stock) or no change. Each week\'s dates sit beside it, on a laptop and a phone. Each line starts with the figure it compares. Costing: Cost per pick, Picks a day, the line picked (for example POWER, paise per pick), Power cost per pick, Labour cost per pick, the head group picked (metres a day), Closing stock, average a day, and B grade, share of folded metres. CFM: the figure charted in the Air and compressor card (Air per 1,000 picks to begin with; a figure per pick is weighted by picks, per air by air, Average CFM per loom by minutes run, Floor CFM, CFM over target (or over benchmark or best) and the compressor\'s kWh and rupees an average a day). Warp breaks: Warp breaks, per 100k picks for the width shown, over loom-days of 60 minutes or more, as the Rate column; the Last 7 days tile counts the last 7 complete days, so the two can differ when a day is missing. The Trend card: the metric shown for its loom or head group (Hours run for a loom\'s Hours run / stopped / off, Looms running for a head group, Main pressure as the average of the day maxima). The all-trends panel: Effective RPM.'),
      !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? P('On the Realisation tab (owner only) each card\'s line compares its own figure, As sold: Coverage: Share of picks priced (its change in points). Trend and By width: Realisation per pick. Per pick: sale value to profit: Profit per pick (loom cost basis). By loom / By head group: the figure its switches show (Profit per loom per day, Realisation per loom per day or Realisation per pick).') : null]},

    {id: 'g-actions', grp: 'Tabs', title: 'Actions', tab: 'actions', body: [
      P('The to-do list for the latest day. The tiles compare the day with the average of the days before it.'),
      B(K('Needs a head group:', 'the first card on the tab. It stays folded, saying "Nothing to assign", while every style has a head group, and opens by itself as soon as a style on the looms or the costing sheet is waiting for one.'),
        K('Trend:', 'near the foot of the tab, after Where the saving is: one head group or one loom day by day against its benchmark and best, with a Metric list (efficiency, RPM, effective RPM, CFM, air per 1,000 picks, main pressure and warp breaks' + (!plant && typeof fxOn === 'function' && fxOn() ? ', and realisation per loom per day and in total' : '') + '). It opens on the day\'s biggest head group on the width picked; the ↗ next to a loom or head group in a table on this tab loads it into the card. It was on the Quality tab before 24 Nov.'),
        K('Work on these first:', 'the five looms worth most to fix that day, each with why (what is off and by how much) and its impact. Rupees a day = lost picks × the day\'s fixed and attendance-following cost per pick (costs that run whether the loom weaves or not), plus excess air × the compressor\'s rupees per ft³ of air saved (the energy rate on the CFM tab), plus that loom\'s step of the floor ladder. A loom whose warp breaks are high is flagged to check the beam first. Under each loom, the day its quality last changed in the loom data (the last 60 complete days), or "No quality change since" the first day it holds. A loom whose head group changed in either of the last 2 shifts is left out (listed under the card with the day and shift of the change) until it has run 2 shifts on the new head group. Without the day\'s costing it ranks by lost picks, then extra air.')),
      !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? P('Tiles that open a view (owner): Picks, Efficiency, Total CFM consumption, Powered down, Floor pressure, Realisation per pick, Folding shortage and Break-even realisation show › after their name. On a laptop, point at one to read what it opens; on a phone the same words sit under the tile. Tap one (or press Enter) and its view opens under the tiles; tap it again, or press Close on the view, to shut it. One view is open at a time, and none is open when the app loads.') : null,
      !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? B(K('Picks by quality:', 'each quality\'s picks (fabric picks ÷ 39.37, in lakh) and its share of the day\'s, as bars rather than a pie: with this many qualities a pie\'s slices are too thin to compare. The Total row is the tile.'),
        K('Efficiency by quality:', `minutes run ÷ (minutes run + stopped) for each quality, against the ${eff}% line; a quality below it is drawn red. The Total row is the tile.`),
        K('Average CFM per loom by quality:', 'each quality\'s air ÷ the minutes its looms ran, against the floor\'s average (dashed), with its Total CFM (air ÷ 1,440 minutes) and its share of the floor\'s air. The Total row is the Average CFM per loom and Total CFM consumption tiles. The Total CFM consumption tile\'s note gives the floor\'s average CFM per loom too.'),
        K('Powered down, loom by loom:', 'each loom powered down for part or all of the day, its quality that day (or, for a loom that did not run, the last quality it ran) and how long, in h; switch to Head-group-wise for each quality\'s total. The Total row is the tile.'),
        K('Looms at the floor pressure:', 'the looms whose main pressure was the day\'s highest (both widths: one compressor serves the floor), with their quality, and the next level down: bring every loom at the floor down to it and the floor drops that much. Floor ladder on Pressure ›, under the list, opens the whole ladder.'),
        K('Realisation per pick by quality:', 'each quality\'s realisation ÷ its priced picks (As sold), against the floor\'s figure (dashed); a quality below it is drawn red. A quality with nothing priced is named under the chart with its reason, never drawn as 0. The Total row is the tile.'),
        K('Folding shortage by day:', 'each costing day\'s own shortage (dashed) and the month to date up to it (the tile\'s figure; it starts again on the 1st), with its own period buttons (7 days, 14 days, 30 days, Month to date, Dates; Month to date to begin with, "MTD" on a phone) and a this week vs last week line. A day missing a figure is left out and named in the table.'),
        K('Break-even realisation by day:', 'the break-even of each costing day up to the day shown, with the same period buttons (Month to date to begin with), the period\'s average as a dashed line (its cost ÷ its loom-days running, so a day with more looms weighs more) and a this week vs last week line.')) : null,
      P('Target cost per pick (tap the tile to open Where the saving is): the day\'s cost per pick, As entered (the plant\'s power units, without the power correction), if every loom that ran hit its targets. It uses the same day as Actions and never another day: when that day\'s costing is not uploaded yet it says so (' + (!plant && typeof fxIsOwner === 'function' && fxIsOwner() ? 'see Files per day on Data health' : 'tell the owner') + '). It has no period buttons and no week line.'),
      B(K('Where the saving is:', 'the steps in order, so they add up, each in paise per pick and rupees for the day: 1. every loom at its target CFM (the air saved × the energy rate on the CFM tab, at the compressor\'s ₹ a unit that day); 2. the compressor at the set point needed with every loom at its best main pressure (floor + margin; for pressure the target is the best, whatever the Pressure tab\'s Reference switch shows), on the air left after step 1; 3. every loom at its target effective RPM (93% of target RPM; a loom already above adds nothing), with the same fixed costs shared over more picks, so its ₹ reads \'₹0 · same rupees, more picks\' (only its paise move) and the ₹ column adds exactly to the Target cost per pick row; 4. the costs that grow with the extra picks: compressor power (the compressor\'s share of power only, for the extra picks\' air at the same energy rate), warping and transport at the rates on the day\'s costing file, packing at the month-to-date rupees per metre; 5. no B grade and no cut pieces (the B grade expense line and the cut piece loss both taken as 0). Every other expense line stays the same. Extra metres = each loom\'s extra picks ÷ the picks per metre of its quality on the day\'s costing.'),
        K('The table:', 'Loom-wise or Head-group-wise, each row\'s CFM saving, Extra picks, Extra metres and Effect on cost per pick (how much it moves the target cost per pick). A loom with no target, or whose quality has no picks per metre on the day\'s costing, is a gap, never 0: it sorts last with a link to Targets or Costing. Each step\'s link goes to the tab behind it.'),
        K('Folding, beams and dispatch lag the looms:', 'valuing warping, transport and packing on metres woven assumes they catch up within the month.')),
      P('Folding shortage (a tile on Actions, beside Target cost per pick): ' + 'month to date (days left out of costing are not counted): 1 − (A-grade folded picks + B grade picks + cut piece picks) ÷ production picks. B grade picks are each register entry\'s metres × its quality\'s picks per metre (from an earlier day if its taka was folded later); cut pieces use the floor\'s average picks per metre. A day missing one of these figures is left out and the tile says how many days it counts.'),
      !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? B(K('Target profit per pick (owner only):', 'As sold, both widths: the target realisation per pick (each loom-day\'s target picks × its own realisation per pick, so it moves only with the mix) less the target folded cost per pick (the corrected costing\'s folded cost with the same savings, extra picks and added costs, no B grade or cut pieces, and A-grade folded picks = target picks × (1 − folding shortage)). Coverage is the share of the day\'s picks that are priced and have a target. Under it, "Target:" gives the same profit in rupees for the day: the profit per pick × the target A-grade folded picks, every target pick taken as A grade less the folding shortage, with no B grade loss assumed.'),
        K('Folded cost per pick by quality (owner only):', 'tap the Folded cost per pick tile: each quality\'s folded cost per pick for the day on the date chip and month to date, on the loom cost method (the compressor by its air, the rest of POWER + 2 paise a pick + the cut piece loss by picks, every other head ÷ the looms running, and its own B grade), ÷ its A-grade folded picks: its picks × (1 − the month-to-date folding shortage, the same for every quality, as the note at the top says) − its B grade picks − its share of the cut piece picks. Rows for 190 cm, 280 cm and both widths. "—" when the day has no costing or loom data, or a loom of the quality had no CFM reading; the = beside the title has a worked example.'),
        K('Break-even realisation (owner only):', 'the full-width tile after the others: what each running loom has to realise in the day to cover its cost, (operating expenses + cut piece loss on the corrected costing + 2 paise a pick + net B grade) ÷ looms running, the same figure as on the Realisation tab. Tap it for Break-even realisation by day.')) : null,
      P('A loom style with no head group yet makes the Needs a head group card at the top open by itself, with a red badge on Actions: answer it there (or in the Config Sheet) so its looms are benchmarked. To see every loom against its references, open Quality, CFM, Effective RPM or Pressure.'),
      B(ed ? K('Needs a head group:', 'pick a head group for each style, then press Save all, or Save on one row. A pick not yet saved stays while you save the others. Saved answers apply on the next daily run (every hour, 10:40 to 16:40 IST), or press Reload data under the card to apply them now.') : null, (ed ? K('Reload data:', 'starts the daily run now (it otherwise runs every hour, 10:40 to 16:40 IST), so head groups saved in the app apply at once instead of at the next run. Targets need no reload: they apply in the app the moment you save. Save your changes first. It takes about 5 to 10 minutes; the button stays greyed out meanwhile and for 10 minutes after you press it. When it finishes, the app fetches the new figures and a bar says so, here or the next time you open the app; the owner also gets an email or phone notice once that channel is set up.') : null)),
      P('Head-group names: a head group linked to a fabric on Head-group links is called by that fabric\'s name, exactly as the fabric app shows it (name and reed space), from the next hourly run, on every tab and for all its history. The small 190 or 280 label beside a name is the loom width, since one fabric can run on both. The name in the Config Sheet\'s Style map stays as it is: targets and switches saved under it carry over. A rename approved from the fabric app renames the head group; undoing the link gives the old name back. Head groups that end up with one name on one width are one head group: their looms are benchmarked and ranked together, each keeps its own link (a loom-day is priced by the group with most picks that day), and the targets and switches are the ones of the group already called by that name, else the busiest.'),
      B(K('The line in each tile:', 'the last 7 complete days up to the day shown; the dot is that day. Hover it for each day\'s figure.'))]},
    {id: 'g-quality', grp: 'Tabs', title: 'Quality', tab: 'quality', body: [
      P('One row per head group for the day shown (looms that ran at least 60 minutes), against its benchmark, best and your target, for every metric side by side. Drift alerts compare the latest day with the 7 days before it (and week on week once there are 14 days), so a slow slide shows up before it becomes the norm. Open a head group for its looms.'),
      B(K('Gap to the reference (the heat grid at the top):', `one cell per head group and metric: the day's figure as a % above (+) or below (−) the reference you pick with Benchmark / Best / Target (kept on this device). Green is better, red is worse, and the colour is full at ${HEAT_FULL}% or more. Efficiency is always against the ${eff}% line; warp breaks against the head group's median rate, so it has no best or target. A grey cell says why it has no reference (for example "no target"). Main pressure has no target: on Target its column uses the head group\'s best main pressure, and the note says so. Point at any cell and a note shows the head group's figure for the day (Current) and the reference's; a cell with a figure also shows it when you move to it with the Tab key. Click it to open the head group. A phone cannot point: tap the cell to open the head group, which shows both figures.`))]},
    {id: 'g-benchmarks', grp: 'Tabs', title: 'Benchmarks', tab: 'benchmarks', body: [
      P('Pick a quality on the left to see its benchmark and best for every metric, then the loom-days behind them: the two loom-days either side of the percentile, their weights, and every loom-day at or past the benchmark. Use it when a benchmark looks too easy or too hard; it shows exactly which runs set it.'),
      !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? B(K('paise/pick (owner only):', 'the third line beside each quality in the list: its realisation per pick on the latest day, As sold, as on the Realisation tab. "not priced" means nothing of that quality was priced that day (a gap, not zero): see Coverage on the Realisation tab.')) : null]},
    {id: 'g-cfm', grp: 'Tabs', title: 'CFM', tab: 'cfm', body: [
      P('Air is the biggest lever on compressor power. Benchmark CFM is the head group\'s benchmark air per 1,000 picks at the RPM the loom actually ran, so a loom is not rewarded for running slow.'),
      B(K('Air and compressor (the second card):', 'whole floor, both widths (one compressor serves them). Three views, CFM, Air per 1,000 picks and Compressor power; it opens on Air per 1,000 picks every time. On a phone the buttons read CFM, Air and Compressor, and the periods 7d, 14d, 30d, All days and Dates.'),
        K('CFM view:', 'Floor CFM (the floor\'s air for the day ÷ 1,440 minutes), CFM over target (Floor CFM less its reference line; it reads CFM over benchmark or CFM over best when the Reference line switch says so, and the note gives it as a % of Floor CFM), Average CFM per loom (the floor\'s air ÷ the minutes the looms ran) and Cost per CFM (the compressor\'s rupees for the day ÷ Floor CFM, in ₹ a day per CFM).'),
        K('Air per 1,000 picks view:', 'Air per 1,000 picks (floor air ÷ fabric picks × 1,000), Air over target (the same, less its reference line, in ft³ per 1,000 picks), Energy per lakh picks (the compressor\'s kWh) and Compressor cost per pick in paise (picks = fabric picks ÷ 39.37, as on Costing).'),
        K('Compressor power view:', 'Compressor energy (the Power (Compressor) line\'s kWh), Cost (its rupees, with the ₹ a unit), Energy per air (kWh per 1,000 ft³ of the floor\'s air) and Cost per air (₹ per 1,000 ft³). When the compressor\'s kWh changes by under 2% over the days charted, the card says so: Energy per air and Cost per air then move mostly with the air. For 5 to 19 Nov 2026 the kWh comes from the weaving compressor\'s meter reading, because the costing sheet carried one day\'s figure forward then; the rupees are that kWh × the costing sheet\'s ₹ a unit. The tile\'s note says which.'),
        K('Charting a tile:', 'tap a tile (› after its name) to chart that figure day by day (the bold line under the tiles names the one charted); the ringed tile is the one charted, and the this week vs last week line follows it. With no target CFM on any loom, CFM over target and Air over target show "—": set targets on Targets (or tell the owner); with Benchmark or Best picked and no loom carrying one that day, pick another day with the date chip. A compressor figure uses the latest day with a compressor reading and names it when that is not the day shown; a day without one is a gap in its line, never 0.'),
        K('Reference line:', 'the Benchmark, Best and Target buttons above the tiles (Target every time the app opens) draw a dashed line, At target, At benchmark or At best, on the chart of Floor CFM, Average CFM per loom, Air per 1,000 picks, Energy per lakh picks, Compressor cost per pick, Compressor energy and Cost: the same figure with every loom above that reference CFM brought down to it, the rest as they ran (the note under the chart says how many looms have none). The compressor\'s kWh fall by the air taken off × the energy rate (see Energy rate below), and the rupees at the day\'s ₹ a unit, as in step 1 of Target cost per pick. The boxes above the chart switch each line off or on. Cost per CFM, Energy per air and Cost per air have no line, because on that basis they would not change. CFM over target and Air over target follow the same buttons (they read over benchmark or over best when those are picked). These buttons are the card\'s own: the tab\'s own switch further down (Bring looms to benchmark, To best, To target; on a phone Benchmark, Best, Target) sets the other CFM cards, not this one.'),
        K('If every loom ran at its reference CFM (the first card):', 'each loom above its reference (benchmark, best or target: your choice) brought down to it; looms already below stay. Since 24 Nov it is one card with what the saving is worth. Total CFM now is the floor\'s 24-h average draw; Total CFM after the work is the same picks with every loom at or below its reference, and its note gives the air saved (CFM and ft³ a day) and its share of the floor\'s air.'),
          K('Cost per pick saved:', 'the air saved × the energy rate (kWh per 1,000 ft³) × the compressor\'s ₹ a unit that day gives the kWh and rupees saved a day, in the tile\'s note; ÷ the same looms\' picks (fabric picks ÷ 39.37, as on Costing) gives the paise per pick. In a month is the rupees a day × 30, at that day\'s level. Compressor, that day is the Power (Compressor) line\'s rupees; its note gives its kWh and its cost per pick on the whole floor\'s picks (both widths), and names the day when the day shown has no reading yet. Without a compressor reading on or before the day there are no money tiles, and the card says what to do next.'),
          K('Energy rate:', 'the Energy rate tile on If every loom ran at its reference CFM: the kWh per 1,000 ft³ that cutting air takes off the compressor. It is the slope of a fit of the compressor\'s kWh a day against the floor\'s air over the last 30 days with a reading (from 5 Nov 2026), so part of the energy that does not move with the air is left out and an odd day counts for less. Until the fit is good enough (10 days or more, R² 0.70 or more, and a slope above 0 and below the average) it is the average of those days, and the tile says which. The Worth columns, Work on these first, step 1 of Target cost per pick and the card\'s reference line use the same rate. Energy per air on the Air and compressor card stays the day\'s own average.'),
          K('Against benchmark, best and target, by head group:', 'one row per head group, most excess first unless another Sorting basis is picked, drawn like the by-loom chart: the bar is its CFM now, the tick its benchmark CFM at the RPM it ran, the green dot its best, the diamond your target; +n is the excess over the reference switched at the top. Click a row for the head group.'),
          K('Excess CFM by day:', 'the table at the foot of the tab: each of the last 14 days\' excess over the reference in CFM and ft³, and its share of the floor\'s air. The floor\'s total CFM by day is the Floor CFM line in the Air and compressor card.'),
          K('By loom / vs benchmark:', 'the looms with the most excess first (the default Sorting basis); the bar is now, the dot is the reference.')),
      el('p', {class: 'note', text: 'These savings use the compressor\'s own line in the costing, not the plant\'s whole POWER bill, and are not added to the Pressure savings (the two overlap).'})]},
    {id: 'g-erpm', grp: 'Tabs', title: 'Effective RPM', tab: 'erpm', body: [
      P(`Effective RPM = RPM × efficiency ÷ 100: the picks a loom really makes per minute, counting speed and stoppages together. Benchmark is the 90th percentile of the head group's loom-days, best its highest, target ${etg}% of your target RPM. "Shortfall" (in the table and as the chart's Sorting basis) is how far below the reference a loom runs and "picks short" what that gap cost in the day.`)]},
    {id: 'g-pressure', grp: 'Tabs', title: 'Pressure', tab: 'pressure', body: [
      P('One compressor serves both widths, so this tab always covers all looms. The loom with the highest main pressure sets the floor; the compressor needs to run at that plus a margin (0.4 kgf/cm² today, a row in the Config sheet\'s Settings tab). Bring the high looms down and the set point can come down.'),
      B(K('Floor after the work:', 'the highest pressure left once every loom is at its reference, and which loom holds it.'),
        K('Compressor set point:', 'the pressure the compressor is set to, typed on this tile. ' + (ed ? 'Tap the tile, type it in kgf/cm² and press Save; it applies for everyone at once.' : 'The owner types it in; tell the owner if it is out of date.') + ' Under it, "since": the day it took effect, and "needed": the floor plus the margin, now → after the work. If the set point history could not be read, the tile says so and shows the last set point saved: press Refresh (the round arrow).' + (ed ? ' Each set point is saved with the day it took effect ("Effective from", the day shown to begin with): a day uses the set point in force on it, and the box lists the history. To correct one, type the right set point for the same day.' : '')),
        K('If every loom ran at its reference pressure (the first card):', 'since 24 Nov one card with what lowering the pressure is worth. The reference is Bring looms to benchmark or To best: for pressure the target is really the best, so there is no target button (and no target box on Targets). Each loom above its reference is brought down to it; looms already below, or with no head group or benchmark, stay as they are.'),
        K('Cost per pick saved:', 'your % per 1 kgf/cm² rule (Targets tab) × how far the compressor can come down, in two parts that add up: from its set point to what today\'s floor needs, then from there as the looms come to their reference (a part is 0 where the compressor already runs at or below it, never negative). That share of the compressor\'s kWh and rupees that day, ÷ the whole floor\'s picks, in paise; the note gives the rupees and kWh a day and the share. In a month is the rupees a day × 30. Compressor, that day is the Power (Compressor) line\'s rupees, with its kWh and its cost per pick on the whole floor\'s picks in the note. Without a set point, a margin or a compressor reading there are no money tiles, and the card says what to do next.'),
        K('Floor ladder:', 'the order to work in. Step 1 brings the loom setting the floor down to its reference; the floor then sits at the next-highest loom, and so on for five steps. Green bars are how far each step drops the floor (0 when two looms share the top), and the table adds the energy and money saved so far, from the looms only (the Cost per pick saved tile also counts the set point coming down to what today\'s floor needs, so its saving can be higher). The by-quality table and Head groups holding the floor up count the looms\' part the same way. It stops early when the loom at the top has no reference or is already at it, and says which.'),
        K('Paise per pick:', 'over the whole floor\'s picks, because a pressure saving is a whole-compressor saving.'),
        !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? K('Compressor kWh against the fit (owner only):', 'one point a day: that day\'s compressor kWh less the kWh the energy rate\'s fit gives for its air, as a % of the fitted kWh (0 = on the fit). The Fit switch (Current fit every time the app opens) draws the same against a second fit instead, Air + floor pressure: kWh = a + b × air + p × the day\'s floor pressure, on the days that have one. A bold line gives both fits\' R² for the latest day, and p in kWh per kgf/cm² beside your % rule; the energy rate for the CFM saving keeps the current fit. Point at or tap the chart to read a day: its kWh, the fitted kWh, the difference and how many robust standard deviations it is. A day more than 3 away is marked outlier: check that day\'s reading in the power register. Each day is set against its own last 30 days, so a past day does not move; the first days sit near 0, and outliers are labelled from the 10th day. The period buttons are 7, 14 or 30 days, Month to date (the default) or Dates; on a phone they read 7d, 14d, 30d, MTD and Dates, and the dates the chart covers are written beside them. The note under it gives the fit in use and, once the days hold two set points with 5 days or more each, how much a set point change moves the kWh, beside the 7% rule (the rule stays what the saving uses).') : null,
        K('190 / 280 / All', 'inside the by-loom cards only picks which looms are listed; every total covers all looms.'))]},
    {id: 'g-utilisation', grp: 'Tabs', title: 'Utilisation', tab: 'utilisation', body: [
      P(`Looms powered down for ${OFF_LONG / 60} h or more in the day (a loom missing from a shift file counts as off for that shift), and looms below ${eff}% efficiency on at least ${LOW_EFF_DAYS} of their last ${LOW_EFF_WINDOW} running days. "Likely beam" means the low days line up with a beam change.`),
      B(K('Run, stopped and powered down:', 'the calendar at the top: one row per loom, one column per day for the last 14 days. Each cell is that loom\'s 24 hours stacked from the bottom: blue run, orange stopped, grey powered down. Looms that lost the most hours come first, so a loom that keeps stopping or is often off stands out. Pick a day in Sorting basis to put the looms that lost the most hours that day (stopped + powered down) first. Click a cell to open the loom on that day.'))]},
    {id: 'g-warp', grp: 'Tabs', title: 'Warp breaks', tab: 'warp', body: [
      P('Warp stops point to warping and beam quality more than loom settings. Counts are breaks; rates are breaks per 100,000 picks, so looms on different speeds compare fairly. By quality ranks head groups; pick one for its looms against the head group\'s median. Flagged looms are well above their head group\'s median (by the multiple and floor rate in the settings) on several of their last 5 running days: check the beam (its number is listed) before the loom.'),
      B(K('Break rate by beam:', 'each beam still on its loom that ran in the period, ranked by its break rate over its whole run on the loom. A beam already changed out is left off: it cannot be acted on. The tick is its head group\'s beam line; the strong part of a bar is past it.'),
        !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? K('Realisation lost on each beam (owner only):', 'Warp stops are the minutes each loom stood on warp breaks on that beam (the report\'s "Warp (min)"; weft and other stops are not charged to the beam). Picks lost on warp stops = those minutes × the loom\'s RPM; Realisation lost values them at that day\'s realisation per pick (As sold). Days counted shows how many of the beam\'s days have warp minutes and how many are priced; a day without warp minutes is left out, never counted as 0, and "—" means none of its days has them yet. "no warp minutes yet": days stored before 17 Nov 2026 are read again from the plant files over the next daily runs; if it stays a day later, ask the plant for the full Toyota report. "not priced": see Coverage on the Realisation tab. On a phone each beam is one block with the same names.') : null)]},
    {id: 'g-costing', grp: 'Tabs', title: 'Costing', tab: 'costing', body: [
      P(plant ? 'Built from the plant\'s own costing file, one day at a time, November onward.' : 'Built from the plant\'s costing file, one day at a time, November onward. It stands on its own: metres, picks and looms running can differ from the loom tabs, which use the Toyota reports.'),
      B(K('Cost per pick', '= (total expenses + cut-piece loss) ÷ picks, in paise. Picks = fabric picks ÷ 39.37, the costing sheet\'s basis. B-grade loss is shown separately and not added.'),
        K('Folded cost per pick', 'uses the A-grade folded picks instead, so it moves the other way on a day folding runs ahead of or behind production.'),
        plant ? null : K('Power units', 'opens on the plant\'s figures as entered; Corrected is one tap away.'),
        K('Fixed per day', 'is the share of the day\'s cost that does not change with output.'),
        !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? K('Sheet checks (owner only)', 'the costing run\'s errors and warnings in the plant\'s file that can change a figure the app shows (each says which); the rest stay in the Validation tab and are counted under the list. New / Standing / All picks which are listed and opens on New; Standing means the previous day\'s file had the same finding with the same figures. The New errors and New warnings counts, and the "new errors" in the hourly notification\'s Costing line, count only those findings and do not follow the switch. A grey Not checked tag marks a check that could not run on this file: it counts as a warning and says which figures it would have covered. A day checked before 16 Nov 2026 lists every finding until it is checked again. Then the plant file against the recomputed costing line by line, and the month to date in the file against the sum of the day amounts. "—" means not read or a day missing, never zero.') : null,
        !plant && typeof fxIsOwner === 'function' && fxIsOwner() ? K('Day rules (owner only)', 'days left out of costing (such as the Diwali shutdown, 8 and 9 Nov 2026) and double-pay days (costed at single cost, such as 10 to 12 Nov) are set in the Config sheet\'s Settings tab. The plant\'s month totals still carry them: Sheet checks show that part as expected, and list every line where the plant\'s progressive misses the correct double pay, with the rupee gap.') : null),
      el('div', {class: 'gex'}, el('div', {class: 'note', text: 'Example: why cost per pick moved (made-up figures)'}), exFall()),
      P('Why cost per pick moved: grey bars are the comparison and the day shown; red pushed cost per pick up, green pulled it down. Volume is what the comparison\'s total cost would have been per pick at the day\'s picks: fewer picks spread the fixed cost thinner. Each line after that is its change in rupees ÷ the day\'s picks. The effects add up exactly to the change.'),
      B(K('Compare with (laptop name / phone name):', 'V yesterday / Yesterday is the costing day before (days left out of costing are skipped). V yesterday avg / Avg till yesterday (the default) is the month\'s average day from the 1st up to the day before. V running avg / Month avg is the month\'s average day over every costing day uploaded so far, so 1 Nov against all of November. Select date / Date is any costing day. Averages are picks-weighted: total cost ÷ total picks over those days. On the first costing day, or a month\'s first or only day, there can be nothing to compare with; the card then names the buttons to try (V yesterday / Yesterday, Select date / Date) or says to wait for the next costing day.'),
        K('Shown to 2 decimals:', 'the effects in the bridge are rounded so that the figures on screen add up to the change shown.'),
        K('Cost per pick by cost type:', 'cost per pick day by day (or week by week) as stacked bars: fixed per day, follows attendance, follows output, lumpy, and the cut-piece loss. They add up to the headline cost per pick (the dashed mark and the figure on top). Hover any block for its figure and share; click a cost type in the legend to highlight it across the days. The fixed layer grows on a low-picks day: that is volume, not spending.'),
        K('Converting cost per metre:', 'the Production card\'s day figure as ranked bars, highest first by default. It is the day\'s cost per pick × each quality\'s picks per inch, so the order follows picks per inch.')),
      B(K('Fixed against variable:', 'every cost line is tagged once: fixed per day, follows attendance, follows output, or lumpy (a bill on some days, nothing on others). Read a jump in lumpy lines as timing, not a trend.'),
        K('Production by quality head group:', 'metres, picks and looms by quality, Today or Month to date. Converting cost per metre = the day\'s cost per pick × the quality\'s picks per inch.'),
        K('Stock and dispatch:', 'stock days = closing stock ÷ metres produced (a day, or the month\'s daily average); dispatch % = metres dispatched ÷ metres produced.'),
        K('B grade and cut pieces:', 'metres, share of folded metres and ₹ loss, by head group and by loom (click a loom for its register entries), and the reasons grouped from the register\'s remarks. B grade is costed at 50% of the quality\'s rate, cut pieces at ₹60 a metre.'),
        K('B-grade reasons chart:', 'one bar per reason, most metres first, with its share of all B grade in the period. A remark naming two problems counts under both, so the shares add up to more than 100% and there is no running total.'),
        K('B grade share by head group, latest day and the rest of the period:', 'the latest register day has its own column at the right; the days before it are in 7-day blocks counted back from it. Each cell is the head group\'s B-grade metres ÷ the metres it produced then, stronger red for a higher share. Red across a whole row is a standing problem; red only on the latest day is new. Click a head group (here or in B grade by head group) to open its looms in Loom-wise B grade.'),
        K('Files:', 'each day\'s checks: expense lines add to the total, total ÷ picks matches the sheet, today\'s progressive equals yesterday\'s total.'))]},
    {id: 'g-targets', grp: 'Tabs', title: 'Targets', tab: 'targets', body: [
      P('Set any of target CFM and RPM per head group and width; leave a box empty for none. Main pressure has no target: since 24 Nov the head group\'s best main pressure stands in wherever a pressure target was used (Target cost per pick step 2, Work on these first, the Quality grid on Target). Targets apply on every tab as soon as you save, and are kept in the Config Sheet. "Now" beside each box is the latest day, with bm and best for comparison. Also here: single or double panna for 280 cm head groups, and the compressor\'s % energy per 1 kgf/cm² of pressure used on the Pressure tab. Saving needs the Edit targets role.'),
      B(K('The small bar beside each box:', 'now (lime bar), benchmark (tick), best (green dot) and your target (hollow diamond, as you type it) on one scale. A target that sits on the wrong side of the benchmark, looser than what the head group already does, is obvious at a glance.'),
        ed ? K('Save all:', '(above and below the table) saves every head group whose boxes you changed, in one go, and says how many it saved. What you type in other rows is kept while one row saves.') : null)]},
    {id: 'g-data', grp: 'Tabs', title: 'Data health', tab: 'data', body: [
      P('Which days are complete, every file the daily run looked at (and why one was set aside), other alerts from the run, and the settings in use (edited in the Settings tab of the Config Sheet). Look here first when a day is missing or a figure looks wrong.'),
      B(K('Last 30 days:', 'a calendar, Monday first: green days are complete (both shifts in), red days are missing or incomplete, grey days come after the newest file and are not in yet. A red day in the middle is a gap to chase.'),
        K('Files per day:', 'one bar per day of the files the run looked at, coloured by what it did with them: read, set aside (the Files table says why), duplicate or superseded. Two read files is a normal day. Under it, Costing file lists the days whose costing was not one file named costing.xlsx: the run finds the costing file by what is in it, so a renamed copy is read; the day is always the folder\'s date; with two or more costing files in a folder the newest is read. Each note there has its next step (for example, ask the plant to keep one costing file in each day folder).'),
        K('Backup age:', 'when the nightly database backup (02:17 IST) last succeeded. Ok up to 26 hours; late after that, which means the nightly backup has stopped: tell the owner. "No record yet" until the first backup after 17 Nov.'), (ed ? K('Reload data:', 'starts the daily run now (it otherwise runs every hour, 10:40 to 16:40 IST), so head groups saved in the app apply at once instead of at the next run. Targets need no reload: they apply in the app the moment you save. Save your changes first. It takes about 5 to 10 minutes; the button stays greyed out meanwhile and for 10 minutes after you press it. When it finishes, the app fetches the new figures and a bar says so, here or the next time you open the app; the owner also gets an email or phone notice once that channel is set up.') : null))]},
    {id: 'g-access', grp: 'Tabs', title: 'Access', tab: 'access', admin: true, body: [
      P('Anyone can ask for access by signing in with a code sent to their email; they see nothing until you approve them with a role here. You can also add someone directly, change a role, or remove a person (their access stops at once).'),
      B(K('Plant view:', 'every tab except Data health and this one, read only; Costing in the plant\'s own figures.'), K('View:', 'every tab, read only.'), K('Edit targets:', 'also saves targets, head-group answers and switches.'), K('Admin:', 'also this screen.'))]},
    {id: 'g-fabric', grp: 'Tabs', title: 'Fabric health', tab: 'fabric', admin: true, body: [
      P('What the app last read from the fabric database app for Weavelon 2. The read is view-only: it never changes the fabric app, and no figure in this app uses these values yet. Reads run after each hourly run and when you tap Check now.'),
      B(K('Flags in red:', 'no price, no PPI, a missing warp or weft line, a yarn with no rate, or a value that cannot be read. These would stop a fabric being valued.'),
        K('Flags in amber:', 'the same on-screen name as another record, assigned to another unit too, or a name that looks like a sample, test or copy.'),
        K('A stopped read:', 'when a column or tab the app needs is missing, or Weavelon 2 cannot be confirmed, nothing is written until the fabric app is fixed. (The "more than 5 fabrics changed" stop was switched off on 11 Nov 2026; changed fabrics are only listed.)'))]},
    {id: 'g-approvals', grp: 'Tabs', title: 'Approvals', tab: 'approvals', admin: true, body: [
      P('Every change the fabric app makes to a Weavelon 2 fabric, yarn or rate waits here until you decide. A change shows once it has held for about 30 minutes, so quick trials never arrive; a value changed back before you decide withdraws itself.'),
      B(K('Money changes:', 'price, sale terms, construction, yarn lines, yarn counts and rates. One at a time, each with an effective-from date: "new from a date" (the world changed) or "correction" (the old value was wrong for its whole period). Past and future dates work. Preview the impact first; a jump over 25% asks again.'),
        K('Descriptive changes:', 'names, weave, notes: tick and approve together in one tap.'),
        K('Rejected:', 'the fabric app says one thing, you kept another. Asked again only if the fabric app changes it once more. "Approve after all" is there.'),
        K('History and undo:', 'every decision, with who and when. Undo saves the reversal as a new version and puts the change back in Pending; nothing is erased.'))]},
    {id: 'g-masters', grp: 'Tabs', title: 'Fabric masters', tab: 'masters', admin: true, body: [
      P('The dashboard\'s own copy of the Weavelon 2 fabrics, yarns and rates. It starts with a first import you review fabric by fabric (first rates from 1 Nov 2026); after that only an approval adds to it, and every change is a new dated entry.'),
      B(K('Not imported:', 'fabrics you skipped. Bring one in and it comes back as a new-fabric request.'), K('Pause the sync:', 'stops the reads and requests; the masters stay as they are.'),
        K('Realisation switch:', 'only Divyam, once the first import is accepted and the independent review is recorded.'))]},
    {id: 'g-links', grp: 'Tabs', title: 'Head-group links', tab: 'links', admin: true, body: [
      P('Which fabric each loom head group is, per loom width: one greige and one RFD record, covering every style name you grouped under it (a head group is the quality). Suggested from the 4-digit codes in those style names, narrowed by a reed space in a name and what fits the loom; never from a name alone, and never linked until you confirm. Unlinked picks are shown as a gap in the analysis.'),
      B(K('As sold on:', 'one tap per linked head group picks the record the Realisation tab\'s As sold view values it on, greige or RFD. Blank means greige where a greige record is linked, else RFD. The choice is kept with the link and survives undo.'))]},
    {id: 'g-realisation', grp: 'Tabs', title: 'Realisation', tab: 'realisation', admin: true, body: [
      P('Sale value at prevailing rate, realisation (sale value less standard yarn cost) and profit on the loom cost basis, As sold, in rupees, paise per pick and rupees per loom per day. Built from approved masters only; what cannot be valued is a gap with its reason, never a zero and never a guess.'),
      B(K('Profit (loom cost basis):', 'the one profit, everywhere on this tab, in the hourly notification and in Corrections: realisation less each loom\'s loom cost and its own B grade. The loom cost splits the day\'s cost (operating expenses and cut piece loss on the corrected costing, + 2 paise a pick, the standard POWER correction) in four: the compressor by air (the loom\'s air in the day, CFM × run minutes, × the day\'s compressor ₹ per ft³); the rest of POWER + the 2 paise + the cut piece loss, the same paise on every pick; and every other head ÷ the looms that ran that day (any run time, both widths). A day with no compressor reading puts all of POWER in the per pick part. A loom that changed head group that day shares its air and per loom parts by picks. A loom with no CFM reading that day has no loom cost profit ("no CFM reading for the loom" in Coverage; see Files per day on Data health). On a phone the Profit tile\'s label reads "Profit · loom cost".'),
        K('Loom cost of unpriced looms:', 'a loom that ran but is not priced (no link, no rate, or no fabric record) or wove no picks still costs its loom cost for the day. It is not recovered: the floor\'s and each width\'s profit has it taken off, and the Profit tile says so on its "incl." line, which opens Coverage; the loom-days that wove no picks are named apart ("of 5 loom-days: 3 not priced, 2 with no picks woven"). On a day where nothing is priced the profit is "—" and the tile names the loom cost not recovered; the month to date tile and Trend week by week still take it off. By loom and By head group never carry it: an unpriced loom or head group stays a gap. "—" also means no costing day yet or no loom data for the day (see Files per day on Data health), or no loom ran (pick another day with the date chip).')),
      B(K('Basis:', 'As sold only: each head group on its own default record, greige where a greige record is linked, else RFD, or the record you set with one tap on Head-group links.'),
        K('Corrections:', 'at the top: "No corrections yet" until a day already announced in the hourly notification has changed since: its realisation or its profit (loom cost basis) moved by ₹500 or more, for example after an approval dated in the past, an undo, a new head-group link or a costing re-read. The figures are As sold, as in the notification. One row per day (on a phone, one block per day): why, the changes in realisation and profit, the figures told and now, and when the correction was sent (IST); "new" marks a day not read yet and "—" a figure that could not be worked out (nothing priced, no costing day, or for the loom cost basis no loom data; corrections sent before 23 Nov 2026 have no loom cost figure), never a zero. When the loom cost profit of a day already announced appears for the first time, or is worked out on the new loom cost method of 24 Nov 2026 for the first time, it is stored quietly, with no correction. Tap a day to open it. The last 31 days are checked every hour the daily run runs (10:40 to 16:40 IST) and the card keeps the last 30 corrections sent. The correction also goes in the hourly notification; the phone notice names the days only. A number on Realisation in the side menu (on a phone, on More and on Realisation inside it) counts the corrected days not yet read; opening Realisation marks them read.'),
        K('7-day lines:', 'on a laptop, a small line beside Realisation in the side menu shows the whole floor\'s realisation per pick (paise, As sold, both widths) for the last 7 days up to the day shown, with the latest day\'s figure under the name ("… paise/pick"); hover the line for each of the 7 days. A loom\'s panel has the same line for that loom under its Realisation heading, on a laptop and a phone. A phone has no side menu: the nearest there is the Realisation per pick tile on Actions, whose 7-day line follows the loom width picked (190 cm, 280 cm or both), so it matches the side menu\'s line only on Both widths. A day with nothing priced is a gap in the line, never zero.'),
        K('Sale value at prevailing rate:', 'the day\'s sale value in ₹ lakh with the average sale rate a metre (sale value ÷ the metres priced) and the share of picks priced.'),
        K('Profit tiles:', 'Profit (loom cost basis) for the day on the date chip in ₹ lakh, with paise per pick (÷ costed picks) and ₹ per loom per day (÷ every loom-day running), and the "incl." line when looms that ran are not priced; its change against the earlier days and its 7-day line. Profit, month to date (loom cost basis) is the same over the month up to that day; on a phone its label reads "Profit · MTD". On a laptop the six tiles sit 3 × 2; on a phone 2 × 3.'),
        K('Break-even realisation:', 'the third tile: what each loom has to realise on the day on the date chip to cover the day\'s cost, (operating expenses + cut piece loss on the corrected costing + 2 paise a pick + net B grade, the same total the loom cost basis shares out) ÷ the looms running that day, in ₹ a loom a day. It is the same figure as the Break-even realisation tile on Actions. Under it, the Profit tile\'s ₹ per loom per day and how far above (green) or below (red) break-even that is; when every loom is priced, realisation a loom − break-even = that profit. It shows "—" and says why when the day has no costing yet or its costing has no folded cost per pick or A-grade folded picks (see Files per day on Data health), or when no loom ran that day (pick another day with the date chip).'),
        K('Coverage:', 'one bar of priced-and-costed, priced-only and gap picks, with every reason and a link to where it is put right (Head-group links, Approvals, Fabric masters, Costing). Below 90% priced the headline figures are dimmed. Under it, "Loom cost not recovered": the loom cost of running loom-days that are not priced, by reason; any loom-day with picks but no run minutes (it carries only the per pick parts); and the loom cost check: both widths, the loom costs and B grade charged against the plant\'s folded cost with the 2 paise a pick, which must be equal (a difference shows in red with its next step).'),
        K('Trend:', 'realisation, Profit (loom cost) as a solid line and sale value (dashed) per pick each day, toggle boxes for the lines, the period from the sticky bar, weekly on request past 12 days (a week takes off the loom cost not recovered on its days with nothing priced), a pan window for long periods. Dashed markers are days a money approval took effect; hover one to read it. Click a point for that day\'s loom-days.'),
        K('By loom / By head group:', 'right after Trend: Profit (loom cost) on every load, realisation (₹ per loom per day) or realisation per pick (paise) as bars either side of zero, with the plant as the dashed line, at Running, Benchmark, Best or Target effective RPM (the loom cost stays as it was and only B grade scales with the picks). The table\'s three profit columns are on the loom cost basis. Every table and ranked bar chart in the app has a Sorting basis picker and Ascending / Descending; every line chart shows the day you point at under it, with Open this day.'),
        K('Per pick: sale value to profit:', 'sale value → yarn → loom cost → B grade → unpriced looms → profit, in paise, over costed loom-days only so the steps add up exactly. Every row of By loom, By head group and By width opens the loom-days behind it with the same chart for that subject (a loom or head group has no unpriced looms step), and a table of its loom-days with their loom cost and profit; loom numbers and head groups still open their own panels.'),
        K('Lost realisation:', 'the Actions tab\'s lost picks (below the efficiency line, or RPM under its reference) for every day of the period × that loom-day\'s realisation per pick, per loom and per head group, with a period total and the last 7 days as a trend. A lost pick on an unpriced loom-day is counted, not valued.'))]},
  ];
  // Plant view (10 Nov 2026): every section except Data health and Access; Costing in the plant's own figures.
  if (typeof wkGuideLinks === 'function') for (const x of all) { const w = x.tab ? wkGuideLinks(x.tab) : null; if (w) x.body = [...x.body, w]; }   // Round J: each tab's section links to the Working of the marks on that tab
  return all.filter((x) => (x.id !== 'g-realisation' || (typeof fxAnalysisOn === 'function' && fxAnalysisOn())) && (plant ? !['g-data', 'g-access', 'g-fabric', 'g-approvals', 'g-masters', 'g-links', 'g-realisation'].includes(x.id) : !(x.admin && !(typeof ME !== 'undefined' && ME && ME.role === 'admin'))));
}

function openGuide() {
  GUIDE_Q = '';
  pushView(() => guideView());
  const id = GUIDE_TABS[TAB];
  if (id) requestAnimationFrame(() => { const t = panelEl().querySelector('#' + id); if (t) { t.classList.add('here'); t.scrollIntoView({block: 'start'}); } });
}
function guideView() {
  const secs = guideSections(), here = GUIDE_TABS[TAB];
  const body = el('div', {class: 'guide'});
  const draw = () => {
    const q = GUIDE_Q.trim().toLowerCase();
    const shown = secs.filter((x) => !q || (x.title + ' ' + x.body.map((b) => b.textContent || '').join(' ')).toLowerCase().includes(q));
    const groups = [...new Set(shown.map((x) => x.grp))];
    body.replaceChildren(
      el('nav', {class: 'gtoc', 'aria-label': 'Guide contents'}, groups.map((g) => el('div', {}, el('h4', {text: g}),
        el('div', {class: 'gchips'}, shown.filter((x) => x.grp === g).map((x) => el('button', {type: 'button', class: 'chip' + (x.id === here ? ' on' : ''), text: x.title,
          onclick: () => { const t = body.querySelector('#' + x.id); if (t) t.scrollIntoView({behavior: 'smooth', block: 'start'}); }})))))),
      ...(shown.length ? shown.map((x) => el('section', {class: 'gsec' + (x.id === here ? ' here' : ''), id: x.id},
        el('h3', {}, x.title, x.id === here ? el('span', {class: 'pill lime', text: 'this tab'}) : null,
          x.tab && x.tab !== TAB ? el('button', {class: 'link', type: 'button', text: 'Open tab ›', onclick: () => { closePanel(); setTab(x.tab); }}) : null),
        ...x.body.filter(Boolean))) : [el('p', {class: 'empty', text: 'Nothing in the guide matches. Try a shorter word.'})]));
  };
  const box = el('input', {type: 'search', class: 'gsearch', placeholder: 'Search the guide', 'aria-label': 'Search the guide', value: GUIDE_Q,
    oninput: (e) => { GUIDE_Q = e.target.value; draw(); }});
  draw();
  return {title: 'Guide', sub: 'What each tab shows, how its figures are worked out, and what to do with them', body: [el('div', {class: 'guide'}, box), body]};
}
